{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Suntem la 8 kilometri după Lugoj și mai avem 35 de kilometri până la Caransebeș."
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Următoarea oprire e la OMV, în 12 kilometri."
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Pe drum, la 90 km, este Cetatea Devei, o cetate medievală pe un deal vulcanic, cu telecabină."
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Pe drum e Cetatea Devei, o cetate medievală pe un deal vulcanic, cu telecabină, aflată în 90 km."
    }
  ]
}

{
  "actions": [
    {
      "type": "create_reminder",
      "task": "o cafea",
      "trigger": {
        "type": "stop_at_category",
        "category": "cafe"
      }
    },
    {
      "type": "ask",
      "to": "driver",
      "question": "Notat: o cafea, la prima cafenea. Bine?",
      "expects": "yes_no"
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Deocamdată îți pot aminti doar la opriri, de exemplu la benzinărie."
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Ai un memento activ: lichid de parbriz, la benzinărie."
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Am deja notat: lichid de parbriz, la benzinărie."
    }
  ]
}

{
  "actions": [
    {
      "type": "complete_reminder",
      "reminder_id": "r1"
    },
    {
      "type": "speak",
      "to": "driver",
      "text": "Am marcat lichidul de parbriz ca fiind făcut."
    }
  ]
}

{
  "actions": [
    {
      "type": "suggest_stop",
      "poi_id": "omv_km42"
    },
    {
      "type": "ask",
      "to": "driver",
      "question": "Oprim la OMV, în 12 km, pentru benzină?",
      "expects": "yes_no"
    }
  ]
}

{
  "actions": [
    {
      "type": "ask",
      "to": "driver",
      "question": "Andrei, pe o scară de la 1 la 9, cât de obosit ești?",
      "expects": "kss"
    }
  ]

{
  "actions": [
    {
      "type": "ask",
      "to": "driver",
      "question": "Andrei, pe o scală de la 1 la 9, cât de obosit ești acum?",
      "expects": "kss"
    }
  ]
}

{
  "actions": [
    {
      "type": "ask",
      "to": "driver",
      "question": "Andrei, vrei să facem o scurtă pauză la următoarea benzinărie?",
      "expects": "yes_no"
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Andrei, conduci foarte prudent și atent. Felicitări!"
    }
  ]
}

{
  "actions": [
    {
      "type": "speak",
      "to": "driver",
      "text": "Te descurci foarte bine, Andrei, atenția e la cote optime."
    }
  ]
}

{
  "actions": [
    {
      "type": "ask",
      "to": "driver",
      "question": "Salut, Andrei! Cu ce te pot ajuta?",
      "expects": "free"
    }
  ]
}
